-- Generated from the authoritative FarmConnect Premium Rooster 180-day operations file.
-- Do not hand-edit mission rows; regenerate with scripts/care-plan/build-mission-seed.mjs.

begin;

insert into public.care_mission_templates (
  day_number, life_stage, primary_mission, feed_grams_min, feed_grams_max, time_schedule, needed_today, feeding_standard,
  supplement_checklist, vaccine_checklist, operations_checklist, housing_checklist,
  health_checklist, evidence_requirements, emergency_stop_rule, completion_gate, catalog_version
) values
(1, 'EARLY BROODING', 'Create permanent rooster ID; record source/hatchery, hatch date, breed/line if verified, initial weight and four baseline photos.', null, null, '[{"time":"05:30–05:40","action":"Biosecurity entry: sign log, wash hands, wear farm-only footwear/clothes, prepare clean tools."},{"time":"05:40–05:55","action":"Silent observation before handling: posture, alertness, breathing, location, droppings and overnight condition."},{"time":"05:55–06:15","action":"Clean drinker; provide fresh potable water; inspect flow, height, leaks and contamination."},{"time":"06:15–06:35","action":"Provide measured morning feed; record offered amount and previous leftovers."},{"time":"06:35–07:00","action":"Individual health inspection: eyes, nostrils, beak/mouth, crop, comb/skin, breast/keel, abdomen, vent, legs and feet."},{"time":"07:00–08:00","action":"No outdoor exercise. Allow normal movement inside the temperature-controlled brooder."},{"time":"11:30–11:45","action":"Midday heat and hydration check: panting, wing spreading, shade, airflow, water and wet litter."},{"time":"15:30–15:45","action":"Second silent health observation and droppings check."},{"time":"15:45–16:10","action":"Provide remaining measured ration when appropriate; refresh water and record intake exceptions."},{"time":"16:10–16:40","action":"Daily special mission and evidence: Create permanent rooster ID; record source/hatchery, hatch date, breed/line if verified, initial weight and four baseline photos."},{"time":"16:40–17:00","action":"Spot-clean housing; remove wet litter/spilled feed; clean feeder; inspect pests and hazards."},{"time":"17:00–17:15","action":"Final headcount, secure housing and complete FarmConnect record."}]'::jsonb, '["Farm-only footwear/clothing, handwashing supplies and correctly prepared footbath","Clean feeder and drinker; potable water","Complete chick starter; free access in shallow feeder; fresh potable water 24/7.","Digital scale for feed; bird scale on scheduled weigh-in days","Clean gloves for examination; dedicated cleaning tools","Dry litter and sealed waste container","Phone/camera with correct date/time for evidence","Rooster ID record and daily caretaker checklist","Isolation pen and veterinarian/LGU veterinary contact available for emergencies"]'::jsonb, '["Observe intake; do not restrict. Record feed offered and leftover.","Never serve moldy, wet, rancid, insect-infested or expired feed.","No layer feed, unprescribed antibiotics, random dewormer or injectable “pampalakas.”","Supplements never replace complete feed; record anything administered.","Water remains available throughout the day; increase access during hot weather."]'::jsonb, '["Healthy, eating complete feed, normal water intake and no heat/transport stress: PLAIN CLEAN WATER ONLY.","Heat/transport/mild dehydration risk: shade, airflow and fresh water corrected first.","Poultry electrolyte is justified and authorized: one product only, exact label rate and short labeled duration recorded.","Vitamin support is veterinarian-directed or label-based for a documented stress/deficiency/recovery reason.","No overlapping vitamin/electrolyte products, homemade salt mixture or continuous routine supplementation.","Weak/not drinking/severe panting/neurologic or respiratory signs: isolated and escalated; supplements are not used to hide illness.","Product (or NONE): __________  Reason: __________  Rate/water volume: __________  Start/end: __________"]'::jsonb, '["Checked hatchery vaccine history and signed veterinarian-approved flock schedule.","Bird examined and healthy enough for vaccination; sick/dehydrated/severely stressed bird is not automatically vaccinated.","Correct disease, product, lot, expiry, dose, route and bird ID verified.","Cold chain and label preparation requirements maintained.","No disinfectant, chlorine, vitamins, electrolytes, antibiotics or other products mixed into vaccine water unless label/veterinarian directs it.","Administration performed by trained/authorized personnel.","Date/time, product, lot, expiry, route, administrator and reaction recorded.","Product-specific take/booster follow-up scheduled.","Vaccine (or NOT DUE): __________  Veterinarian approval/reference: __________  Next review: __________"]'::jsonb, '["Biosecurity entry completed","Silent morning observation completed","Fresh water supplied and drinker cleaned","Morning feed measured and recorded","Full individual health inspection completed","Age-appropriate safe movement completed","Midday heat/hydration inspection completed","Afternoon observation and feeding completed","Special mission completed","Housing spot-cleaned and secured","Photos/weight/documents uploaded when required","Open concern assigned to responsible person with deadline"]'::jsonb, '["Brooder temperature and chick distribution; dry litter; draft-free ventilation.","Keep separate from sick, quarantined, newly arrived and unknown-status birds.","Prevent contact with wild birds, rodents, standing water and contaminated equipment."]'::jsonb, '["Alert and responsive","Eating and drinking normally","Eyes and nostrils clear","Breathing quietly without open-mouth distress at rest","Crop appropriate for time of day","Vent clean; no persistent watery or bloody droppings","Walking evenly; feet and legs free of swelling/wounds","Skin and feathers without untreated wounds or heavy parasites","No sudden weight/intake decline or active quarantine restriction"]'::jsonb, '["Day 1 time-stamped caretaker check-in","Feed offered and leftover; water exception if any","Health status: PASS / WATCH / ISOLATE-AND-ESCALATE","Special mission result: Create permanent rooster ID; record source/hatchery, hatch date, breed/line if verified, initial weight and four baseline photos.","Required photo/weight/document for the mission, when applicable","Corrective action, responsible person and follow-up deadline for every failed item"]'::jsonb, 'Sudden death, severe breathing difficulty, blue/purple comb, facial swelling, twisted neck, tremor, paralysis, bloody diarrhea, multiple sick birds or rapid feed/water drop = isolate safely, stop movement/sale, restrict entry and contact a veterinarian/LGU veterinary office. Do not self-prescribe.', 'Day 1 is COMPLETE only when routine care, special mission, health result and required evidence are recorded. A missing or failed health item remains OPEN and must not be hidden or marked complete.', 'farmconnect-premium-rooster-180-v1'),
